text:
{
  "jobs": [
    {
      "text": "Сохранить финансовую безопасность и не потерять накопления",
      "quote": "Потеряла все свои сбережения, триста тысяч рублей. А я-то знаю, что это обманывают только доверчивых"
    },
    {
      "text": "Поддерживать связь с близкими (внуком, дочерью) без ощущения опеки",
      "quote": "С дочерью общаюсь реже всего... она всё норовит меня «опекать», как маленькую, а я не потерплю такого отношения."
    },
    {
      "text": "Экономить средства на жизненно важные нужды (лекарства, еда)",
      "quote": "пенсии на еду и лекарства еле хватает... Я ведь экономлю каждую копейку"
    },
    {
      "text": "Идентифицировать входящие звонки, чтобы отличить мошенников от важных сообщений (поликлиника, соцзащита)",
      "quote": "Вдруг это из поликлиники насчет анализов или соцзащита про пенсию спрашивает... Я боюсь пропустить важный звонок из-за своей осторожности"
    }
  ],
  "pains": [
    {
      "text": "Страх прослушки и потери приватности разговоров",
      "quote": "боюсь я их, вдруг там кто-то слушает... И вообще, кто этот сервис будет слушать? Вдруг там те же мошенники сидят и собирают информацию о моих родных."
    },
    {
      "text": "Ощущение инфантилизации и контроля со стороны дочери",
      "quote": "Для меня это как допрос, а не общение с взрослым человеком... Мне обидно, когда родной человек считает меня за глупую"
    },
    {
      "text": "Техническая сложность использования смартфонов и приложений",
      "quote": "от этих приложений у меня голова кругом идет... я не умею в этом вашем смартфоне лазить"
    },
    {
      "text": "Тревога из-за невозможности мгновенно верифицировать источник звонка",
      "quote": "Тревога возникает от того, что я не могу сразу определить, кто звонит, ведь на экране только цифры."
    },
    {
      "text": "Обида на то, что её считают доверчивой или глупой",
      "quote": "Мне стало так обидно, что они думают, будто я глупая старуха, которая не знает разницу между банком и мошенником."
    }
  ],
  "current_solutions": [
    {
      "text": "Ручное отклонение подозрительных звонков («класть трубку»)",
      "quote": "Я просто кладу трубку при первом же странном вопросе... даже если это «банк» или «полиция»"
    },
    {
      "text": "Использование кнопочного телефона для основных контактов",
      "quote": "я всё равно больше по кнопочному звоню"
    },
    {
      "text": "Консультация с подругой перед действиями с деньгами",
      "quote": "я всегда спрашиваю у Зины совета перед тем, как сделать хоть какое-то действие с деньгами, мы вдвоем надежнее."
    },
    {
      "text": "Проверка баланса лично через банкомат",
      "quote": "проверяю баланс только через банкомат лично."
    },
    {
      "text": "Настройка белого списка внуком (частичное решение)",
      "quote": "Внук настроил мне белый список, но я всё равно часто беру трубку от незнакомых номеров из любопытства"
    }
  ],
  "barriers": [
    {
      "text": "Недоверие к автоматизированным системам защиты из-за страха прослушки",
      "quote": "Лучше уж я сама буду класть трубку, чем чужие уши будут слушать мои разговоры с Зинаидой."
    },
    {
      "text": "Финансовый барьер: нежелание платить за услуги при низком доходе",
      "quote": "Если бы это стоило больше пятисот рублей в месяц, я бы даже слушать не стала, лучше на лекарства отложу."
    },
    {
      "text": "Технический барьер: зависимость от внука в настройке сложных функций",
      "quote": "А если на смартфоне, то внук должен мне всё настроить, а он занят и не любит объяснять дважды."
    },
    {
      "text": "Психологический барьер: страх случайно заблокировать важный звонок от близких",
      "quote": "я боюсь нажать не туда и потерять связь с дочерью... А вдруг это действительно внук или дочь с нового номера?"
    }
  ],
  "triggers": [
    {
      "text": "Личный опыт потери денег подругой",
      "quote": "Зина моя подруга тоже поначалу усомнилась, но ей сказали про «секретного сотрудника» и она растерялась от страха... Потеряла все свои сбережения"
    },
    {
      "text": "Частые агрессивные звонки с требованием срочных действий",
      "quote": "Вчера звонили, мужской голос такой наглый: «Срочно переведите деньги на безопасный счет»."
    },
    {
      "text": "Новостные сюжеты по телевизору",
      "quote": "мы с ней обсуждаем новости по телевизору, там тоже про мошенников часто говорят."
    }
  ],
  "words": [
    "опекают",
    "наглость",
    "детские сказки",
    "копейки",
    "белый список",
    "гражданка",
    "понт",
    "фальшь",
    "невидимая машина",
    "за кулисами"
  ],
  "surprises": [
    "Респондент сознательно игнорирует настроенный внуком «белый список» и продолжает брать трубки от незнакомцев из любопытства, несмотря на страх.",
    "Главным барьером для внедрения технологических решений является не цена или сложность интерфейса, а параноидальный страх, что сервис защиты сам станет инструментом прослушки («чужие уши»).",
    "Респондент предпочитает ручное управление рисками (самостоятельно класть трубку) автоматизации, считая себя более компетентной благодаря опыту бухгалтера, хотя технически она зависит от внука.",
    "Дочь воспринимается не как помощник в безопасности, а как источник психологического давления («допрос»), поэтому информация о мошенниках скрывается от неё и делится с подругой."
  ]
}
